    private TrackStatus statusOnObservation(TrackStatus current) {
        return switch (current) {
            case LOST -> TrackStatus.REIDENTIFIED;
            case OCCLUDED, CREATED, REIDENTIFIED -> TrackStatus.TRACKING;
            default -> current;
        };
    }

