    @Test
    void staleExpectedVersionRaisesConflictAndKeepsState() {
        service.associate(det("d1", 1000L, "car", 0, 0, 0.9), null, null, null);

        assertThatThrownBy(() -> service.associate(
                det("d2", 2000L, "car", 0.5, 0, 0.9), "T-000001", 1L, 2.0))
