package com.example.starter.service;

import org.springframework.stereotype.Component;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

/**
 * JVM 内按业务键（检测 ID、轨迹 UID、目标类别）分条的可重入锁注册表。
 *
 * <p>仅保证同一 JVM 内互斥（与题干范围一致）；锁的获取/释放时机由
 * {@link TransactionalKeyLock} 绑定到数据库事务，数据库行锁与乐观锁
 * 版本条件仍是最终防线。</p>
 */
@Component
public class DetectionLock {

    private final Map<String, ReentrantLock> locks = new ConcurrentHashMap<>();

    public void lock(String key) {
        locks.computeIfAbsent(key, k -> new ReentrantLock()).lock();
    }

    public void unlock(String key) {
        ReentrantLock lock = locks.get(key);
        if (lock != null) {
            lock.unlock();
        }
    }
}

package com.example.starter.service;

import org.springframework.stereotype.Component;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * 事务期键锁：基于 {@link DetectionLock} 分条互斥，锁一直持有到当前
 * 数据库事务提交或回滚之后才释放。
 *
 * <p>在 afterCompletion 释放而非业务方法返回时释放，是为了堵住
 * “事务尚未提交、其他线程已读到旧版本”的窗口；业务异常导致回滚时
 * 同样会释放，不会死锁。</p>
 */
@Component
public class TransactionalKeyLock {

    private final DetectionLock locks;

    public TransactionalKeyLock(DetectionLock locks) {
        this.locks = locks;
    }

    /**
     * 获取指定键的可重入锁；当前线程必须处于活动事务中，锁在事务完成
     * （提交或回滚）后自动释放。
     */
    public void lockUntilTransactionComplete(String key) {
        locks.lock(key);
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override
                public void afterCompletion(int status) {
                    locks.unlock(key);
                }
            });
        } else {
            // 防御：写方法均在事务内调用；无事务上下文时立即释放避免泄漏。
            locks.unlock(key);
        }
    }
}

