package com.example.starter.service;

import org.springframework.stereotype.Component;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Supplier;

/**
 * 同一 JVM 内按 detectionId 分条的互斥锁。
 *
 * <p>不同检测可并发处理，相同 detectionId 的并发提交串行化：先到者完成全流程并
 * 提交后，后到者通过 processed_detection 去重表拿到首次结果（DUPLICATE），
 * 保证同一检测不会重复关联或重复创建轨迹。数据库唯一约束仍是跨会话的最终防线。</p>
 */
@Component
public class DetectionLock {

    private static final int STRIPES = 256;

    private final Map<Integer, ReentrantLock> locks = new ConcurrentHashMap<>();

    public <T> T withDetectionLock(String detectionId, Supplier<T> action) {
        ReentrantLock lock = locks.computeIfAbsent(stripe(detectionId),
                k -> new ReentrantLock());
        lock.lock();
        try {
            return action.get();
        } finally {
            lock.unlock();
        }
    }

    private static int stripe(String key) {
        return (key.hashCode() & 0x7fffffff) % STRIPES;
    }
}

