package com.example.starter.service;

import com.example.starter.domain.Detection;
import com.example.starter.testsupport.TestDataCleaner;
import com.example.starter.web.dto.AssociateResponse;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

@SpringBootTest
class DiagnosticConcurrencyTest {

    @Autowired
    private TrackLifecycleService service;

    @Autowired
    private TestDataCleaner cleaner;

    @BeforeEach
    void cleanData() {
        cleaner.clean();
    }

    @Test
    void diagnose() throws Exception {
        service.associate(new Detection("d0", 1000L, "cam-1", "car",
                0, 0, 0, 0.9), null, null, null);
        System.out.println("INITIAL VERSION=" + service.getTrack("T-000001").version());

        int threads = 4;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<String>> futures = new java.util.ArrayList<>();
        for (int i = 1; i <= threads; i++) {
            long ts = 2000L + i;
            double x = 0.1 * i;
            Callable<String> task = () -> {
                start.await();
                try {
                    AssociateResponse r = service.associate(
                            new Detection("d-" + ts, ts, "cam-1", "car", x, 0, 0, 0.9),
                            "T-000001", 2L, 5.0);
                    return "OK outcome=" + r.outcome() + " version=" + r.version()
                            + " thread=" + Thread.currentThread().getName();
                } catch (Exception e) {
                    return "ERR " + e.getClass().getSimpleName() + ": " + e.getMessage()
                            + " thread=" + Thread.currentThread().getName();
                }
            };
            futures.add(pool.submit(task));
        }
        start.countDown();
        for (Future<String> f : futures) {
            System.out.println("RESULT> " + f.get(30, TimeUnit.SECONDS));
        }
        pool.shutdownNow();
        pool.awaitTermination(10, TimeUnit.SECONDS);
        System.out.println("FINAL VERSION=" + service.getTrack("T-000001").version());
    }
}

